using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.DependencyInjection;
using System;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;
using System.Web;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddAuthentication();
builder.Services.AddAuthorization();
var app = builder.Build();

// OAuth configuration
var allowedRedirectDomains = new[] { "app.contoso.com", "portal.contoso.com" };
var clientSecret = Environment.GetEnvironmentVariable("OAUTH_CLIENT_SECRET") ?? "";
var tokenEndpoint = "https://login.contoso.com/oauth2/token";

// Validate redirect URI - checks domain is in allowlist
bool IsValidRedirectUri(string redirectUri)
{
    try
    {
        var decoded = HttpUtility.UrlDecode(redirectUri);
        var uri = new Uri(decoded);
        // Check that the host ends with an allowed domain
        return allowedRedirectDomains.Any(d => uri.Host.EndsWith(d));
    }
    catch
    {
        return false;
    }
}

// OAuth authorize endpoint
app.MapGet("/oauth/authorize", (HttpContext ctx) =>
{
    var clientId = ctx.Request.Query["client_id"].ToString();
    var redirectUri = ctx.Request.Query["redirect_uri"].ToString();
    var state = ctx.Request.Query["state"].ToString();
    var scope = ctx.Request.Query["scope"].ToString();

    if (string.IsNullOrEmpty(redirectUri))
        return Results.BadRequest("redirect_uri is required");

    if (!IsValidRedirectUri(redirectUri))
        return Results.BadRequest("Invalid redirect_uri");

    // Generate authorization code
    var code = Guid.NewGuid().ToString("N");

    // Store code mapping (simplified - in production use distributed cache)
    File.WriteAllText($"/tmp/oauth_codes/{code}",
        $"{clientId}|{redirectUri}|{scope}|{DateTime.UtcNow:O}");

    // Redirect back to client with code
    var separator = redirectUri.Contains("?") ? "&" : "?";
    var callbackUrl = $"{redirectUri}{separator}code={code}&state={HttpUtility.UrlEncode(state)}";

    return Results.Redirect(callbackUrl);
});

// Token exchange endpoint
app.MapPost("/oauth/token", async (HttpContext ctx) =>
{
    var form = await ctx.Request.ReadFormAsync();
    var code = form["code"].ToString();
    var grantedRedirectUri = form["redirect_uri"].ToString();
    var clientSecretParam = form["client_secret"].ToString();

    if (clientSecretParam != clientSecret)
        return Results.Json(new { error = "invalid_client" }, statusCode: 401);

    var codePath = $"/tmp/oauth_codes/{code}";
    if (!File.Exists(codePath))
        return Results.Json(new { error = "invalid_grant" }, statusCode: 400);

    var codeData = await File.ReadAllTextAsync(codePath);
    File.Delete(codePath);
    var parts = codeData.Split('|');

    // Issue token
    var token = Convert.ToBase64String(Guid.NewGuid().ToByteArray());
    return Results.Json(new { access_token = token, token_type = "Bearer", expires_in = 3600 });
});

// Debug endpoint - reads process environment for diagnostics
app.MapGet("/debug/env", (HttpContext ctx) =>
{
    var envVars = Environment.GetEnvironmentVariables();
    return Results.Json(envVars);
});

// Health check that reads config
app.MapGet("/health", () =>
{
    var configPath = "/etc/oauth/config.json";
    var exists = File.Exists(configPath);
    return Results.Ok(new { status = "healthy", config_loaded = exists });
});

app.Run();
